package jamiebalfour.zide.languages;
import jamiebalfour.codeeditor.CodeEditorViewFX;
import jamiebalfour.codeeditor.CodeSyntaxModel;
import java.util.Set;
public final class CssLanguage extends LanguageSupport { public CssLanguage(jamiebalfour.zide.editor.ZIDEEditor ignored) { super("css", "CSS", Set.of("css")); } @Override public void configure(CodeEditorViewFX editor) { editor.setLineCommentMarkers(""); editor.setBlockCommentMarkers("/*", "*/"); editor.setQuoteDelimiters("\""); editor.setVariableDelimiters("--"); editor.setContextSeparator(":"); editor.clearKeywords(); editor.clearContextualKeywords(); editor.clearAutoCompleteItems(); for (String property : java.util.List.of("color", "background", "background-color", "font", "font-family", "font-size", "font-weight", "line-height", "margin", "padding", "border", "border-radius", "display", "position", "width", "height", "min-width", "max-width", "grid", "grid-template-columns", "flex", "gap", "align-items", "justify-content", "opacity", "overflow", "content")) { editor.addKeyword(property, CodeSyntaxModel.Style.KEYWORD); editor.addAutoCompleteItem(property, CodeEditorViewFX.AutoCompleteItemType.Keyword); } for (String atRule : java.util.List.of("media", "import", "font-face", "keyframes", "supports", "layer", "namespace")) { editor.addKeyword(atRule, CodeSyntaxModel.Style.TYPE); editor.addAutoCompleteItem(atRule, CodeEditorViewFX.AutoCompleteItemType.Type); } } }
